# 🔌️ Each backend feature both pulls in its own driver dep and forwards to `db`'s same-named
# storage feature (`db::storage_sqlite`/`storage_postgres`/`storage_neo4j`) — one feature name
# controls both the directory backend AND the document/blob storage substrate together, so there
# is no split-brain where one half of a backend is compiled in and the other isn't.
sqlite = ["dep:rusqlite", "db/sqlite"]
postgres = ["dep:sqlx_core", "dep:sqlx_postgres", "db/postgres"]
