# 🏗️ Test-only, cross-target: compiles the real GIS Map profile builder in
# `🌎️hub/🧪️tests/🔏️trusted-catalog-profile/` so the `os-hub` BINARY target's own laws can
# construct a verified catalog and frozen Map binding. `#[cfg(test)]` cannot serve another target, so
# this must be a feature. It never enters a default build.
integration-fixtures = ["native-artifact-execution"]

