# `🖱️ui/🎯️targets/🧊️wgpu/🦀️.rs`'s top docstring for the wgpu-tier split this depends on.
[target.'cfg(not(all(target_arch = "wasm32", target_env = "p2")))'.dependencies]
ui_wgpu = { path = "../../../../../../🔨️modules/🖱️ui/📦️packages/🦀️rust", package = "semio-framework-ui", features = ["wgpu-engine"] }
# 🌉️ `ui_webgpu` backs only `wasm_session`'s browser wasm-pack SDK bridge (`🦀️.rs`'s own
# gate docstring) — its `ui_render` dependency drags `taffy`/`parley`/`swash`/`fontique` (text
# shaping/layout) unconditionally, none of which a WASI guest needs. Narrowed here rather than
# deleted: native keeps it for this crate's own `#[cfg(test)]` suite over the bridge protocol.
ui_webgpu = { path = "../../../../../../🔨️modules/🖱️ui/🖌️render/🎯️targets/🧊️webgpu/📦️packages/🦀️rust", package = "semio-framework-ui-backend-webgpu" }

# 🌉️ Browser byte-ABI and canvas bindings require a JavaScript engine and are excluded from WASI.
[target.'cfg(all(target_arch = "wasm32", not(target_env = "p2")))'.dependencies]
getrandom = { version = "0.3.4", features = ["wasm_js"] }
wasm-bindgen = "0.2.106"
# 🖼️ `surface_canvas` (🕸️wasm/🦀️.rs) binds the node-graph canvas to the shared
# `CanvasGpuSession` out of band from the byte ABI, which cannot carry an element handle.
js-sys = "0.3.83"
web-sys = { version = "0.3.98", features = ["HtmlCanvasElement"] }

# 🎒️ Preview mesh wire laws (pack record body + chunking + LOD cache) — ticket
# 26/09/09/PROCEDURAL-3D-END-TO-END. Declared as its own `[[test]]` so the cross-language wire
# contract stays runnable from this crate's PUBLIC surface alone.
[[test]]
name = "flow_mesh_pack_wire"
path = "../../🧪️tests/🎒️mesh-pack-wire/🦀️.rs"

